import { z } from '../zod'
import { CropSchema } from '../constants/crops'
import { IssueSchema } from '../constants/issues'
import { ProvinceSchema } from '../constants/provinces'
import { RoleSchema } from '../constants/roles'
import { SeverityBandSchema } from '../constants/severity'
import { VerificationStateSchema } from '../constants/verification'
import { DateSchema, DistrictSlugSchema, GeoPointSchema, TimestampSchema } from './common'
import { DiagnosisSchema } from './diagnosis'
import { RegistrationNoSchema } from './registeredProduct'

// Generated by the app before upload, because photos go to Storage first (buildplan.md §2).
export const ObservationIdSchema = z
  .string()
  .regex(/^[A-Za-z0-9_-]{16,64}$/)
  .openapi('ObservationId', {
    description:
      'Generated by the app before uploading photos (a Firestore auto-ID or a UUID v4). First writer wins: once a user has created an observation with this id, no other user can.',
    example: 'k3J9xQ2mW8pL5vR1tY7u',
  })

// Photos live at observations/{uid}/{obsId}/{n}.jpg: the uploader's uid is in the path, so
// infra/storage.rules can bind every upload to its owner.
export const PHOTO_PATH_PATTERN =
  /^observations\/([A-Za-z0-9_-]{1,128})\/([A-Za-z0-9_-]{16,64})\/\d{1,2}\.jpg$/

export const PhotoPathSchema = z.string().regex(PHOTO_PATH_PATTERN).openapi('PhotoPath', {
  description:
    'Cloud Storage object path in the default bucket: observations/{uid}/{obs_id}/{n}.jpg, where uid is the signed-in user (Storage rules refuse any other uid) and n is 0, 1, 2… JPEG only, under 10 MB.',
  example: 'observations/Vn1rKk5yQhWcXz0pB2sLqT4uEa83/k3J9xQ2mW8pL5vR1tY7u/0.jpg',
})

// The uid and observation id encoded in a photo path, or null if it is not one.
export function parsePhotoPath(path: string) {
  const match = PHOTO_PATH_PATTERN.exec(path)
  return match ? { uid: match[1], obsId: match[2] } : null
}

// Geohash base32 alphabet (no a, i, l, o).
const GeohashSchema = z.string().regex(/^[0-9b-hjkmnp-z]{1,12}$/)

export const OBSERVATION_STATUSES = [
  'diagnosing',
  'awaiting_expert_review',
  'recommending',
  'complete',
] as const
export const ObservationStatusSchema = z.enum(OBSERVATION_STATUSES).openapi('ObservationStatus', {
  description:
    'diagnosing: waiting for the AI assessment. awaiting_expert_review: routed to an officer; no recommendation until verified. recommending: diagnosis accepted (or verified), recommendation being prepared. complete: recommendation available. A verify that corrects the issue sends a complete observation back through recommending to complete. Clients MUST treat an unrecognised value as generic in-progress, never as an error.',
})
export type ObservationStatus = z.infer<typeof ObservationStatusSchema>

export const InterventionTypeSchema = z
  .enum(['cultural', 'biological', 'chemical', 'mixed'])
  .openapi('InterventionType')

export const InterventionSchema = z
  .object({
    applied_at: TimestampSchema,
    type: InterventionTypeSchema,
    // Registration numbers from registered_products, never free text.
    products: z.array(RegistrationNoSchema),
    notes: z.string().max(2000),
  })
  .openapi('Intervention')
export type Intervention = z.infer<typeof InterventionSchema>

export const OutcomeSchema = z
  .object({
    followup_at: TimestampSchema,
    severity_band: SeverityBandSchema,
    resolved: z.boolean(),
    notes: z.string().max(2000),
  })
  .openapi('Outcome')
export type Outcome = z.infer<typeof OutcomeSchema>

// observations/{obsId} (technicaldoc.md §4.1). Unrefined shape, for .pick()/.extend() when
// building request schemas; validate documents with ObservationSchema.
export const ObservationBaseSchema = z.object({
  reporter_id: z.string().min(1),
  reporter_role: RoleSchema,
  org_id: z.string().min(1).nullable(),
  created_at: TimestampSchema,
  // Precise. NEVER exposed to Outgrower/commercial views (CLAUDE.md invariant 6).
  location: GeoPointSchema,
  geohash: GeohashSchema,
  // As submitted by the reporter; district_slug is the aggregation key.
  district: z.string().min(1),
  district_slug: DistrictSlugSchema,
  province: ProvinceSchema,
  // Camps are rarely known at capture time.
  camp: z.string().min(1).nullable(),
  crop: CropSchema,
  planting_date: DateSchema.nullable(),
  growth_stage: z.string().nullable(),
  photo_paths: z.array(PhotoPathSchema),
  farmer_description: z.string().max(2000).nullable(),
  status: ObservationStatusSchema,
  diagnosis: DiagnosisSchema.nullable(),
  verification_state: VerificationStateSchema,
  verified_by: z.string().min(1).nullable(),
  verified_issue: IssueSchema.nullable(),
  recommendation_id: z.string().min(1).nullable(),
  intervention: InterventionSchema.nullable(),
  outcome: OutcomeSchema.nullable(),
  // TRUE for every seeded/synthetic row; drives the DemoBadge (CLAUDE.md invariant 5).
  sim: z.boolean(),
})

// An observation routed to expert review never becomes AI_ASSESSED (technicaldoc.md §6).
export const ObservationSchema = ObservationBaseSchema.refine(
  o => !(o.diagnosis?.needs_expert_review && o.verification_state === 'AI_ASSESSED'),
  {
    message: 'An observation flagged for expert review cannot be AI_ASSESSED',
    path: ['verification_state'],
  }
)
export type Observation = z.infer<typeof ObservationSchema>
